and s.shipment_no like concat('%',#{shipmentNo},'%')
and s.shipment_type=#{shipmentType}
and s.warehouse_id=#{warehouseId}
and s.customer_name like concat('%',#{customerName},'%')
and s.status=#{status}
and s.shipment_date=#{shipmentDate}
and s.shipment_date >= #{params.beginTime}
and s.shipment_date < date_add(#{params.endTime}, interval 1 day)
 order by s.shipment_date desc,s.shipment_id desc

